    this.cps = Array.from(text)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof(offset = 0) {
    return this.i + offset >= this.cps.length
  }

  peek(offset = 0) {
    return this.cps[this.i + offset]
