  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.cps[this.i++]
    if (c === '\n') {
      this.line += 1
      this.col = 1
    } else if (c === '\t') {
      this.col = this.col + (4 - ((this.col - 1) % 4))
    } else {
