/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scanner.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    usageError()
  }
  const mode = args[0]

  const text = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scan(text)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let output
  if (mode === 'tokens') {
    output = tokens.map((t) => `${t.pos.line}:${t.pos.col} ${t.kind} ${t.text}\n`).join('')
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind] += 1
    const lines = STAT_KINDS.map((k) => `${k} ${counts[k]}\n`)
    lines.push(`total ${tokens.length}\n`)
    output = lines.join('')
  }
  process.stdout.write(output)
}

